mapper.select:
select cr_rb_template.business_template_id, cr_rb_room.resource_id as training_id, cr_rb_room.name as training_name, cr_rb_template.duration_time, cr_rb_room.difficulty, cr_rb_room.pre_skill, cr_rb_room.train_skill, cr_rb_room.training_status, cr_rb_room.logo, cr_role.role_group from cr_rb_room inner join cr_rb_template on cr_rb_room.template_id = cr_rb_template.resource_id inner join cr_role on cr_role.room_id = cr_rb_room.resource_id where cr_rb_template.business_template_id in
#{businessTemplateId}
and cr_role.user_ids like #{userId};

select cr_team_template.business_template_id, cr_team_room.resource_id as training_id, cr_team_room.name as training_name, cr_team_template.duration_time, cr_team_room.difficulty, cr_team_room.pre_skills as pre_skill, cr_team_room.train_skills as train_skill, cr_team_room.training_status, cr_team_room.logo, cr_role.role_group from cr_team_room inner join cr_team_template on cr_team_room.team_template_id = cr_team_template.resource_id inner join cr_role on cr_role.room_id = cr_team_room.resource_id where cr_team_template.business_template_id in
#{businessTemplateId}
and cr_role.user_ids like #{userId};

select cr_business_template.resource_id as business_template_id, cr_single_template.business_template_id as training_id, cr_business_template.name as training_name, cr_single_template.duration_time, cr_business_template.difficulty, cr_single_template.pre_skills as pre_skill, cr_single_template.train_skills as train_skill, cr_business_template.logo,
(count(train_record.start) + count(nullif(train_record.`end`, 0))) as training_status from cr_business_template inner join cr_single_template on cr_business_template.resource_id = cr_single_template.business_template_id left join (select count(start_time) as start, count(end_time) as `end`, business_template_id from cr_train_record where user_id = #{userId} and business_template_id in
#{businessTemplateId}
group by business_template_id) as train_record on cr_business_template.resource_id = train_record.business_template_id where cr_business_template.resource_id in
#{businessTemplateId}
group by cr_business_template.resource_id
